package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.LastEventIdVO;

class LastEventIdValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of last event id of observed issue")
  void test_last_event_id_value_holder_assign_plain_value() {
    Object holder = new Object();
    LastEventIdValueHolder<Object> value = new LastEventIdValueHolder<>(holder);
    Assertions.assertSame(holder, value.lastEventId("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLastEventIdValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getLastEventId().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.lastEventIdNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLastEventIdValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLastEventId().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of last event id of observed issue")
  void test_last_event_id_value_holder_assign_value_object() {
    Object holder = new Object();
    LastEventIdValueHolder<Object> value = new LastEventIdValueHolder<>(holder);
    LastEventIdVO vo = LastEventIdVO.from("one");
    Assertions.assertFalse(value.getLastEventIdValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.lastEventId(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLastEventIdValue().orElseThrow());
    Assertions.assertSame(holder, value.lastEventId(Optional.empty()));
    Assertions.assertFalse(value.getLastEventIdValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.lastEventId(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLastEventIdValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of last event id of observed issue against the original")
  void test_last_event_id_value_holder_read() {
    Object holder = new Object();
    LastEventIdValueHolder<Object> value = new LastEventIdValueHolder<>(holder);
    LastEventIdVO vo = LastEventIdVO.from("one");
    LastEventIdVO other = LastEventIdVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getLastEventIdValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLastEventId(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLastEventId(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.lastEventId(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLastEventId(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLastEventId(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of last event id of observed issue")
  void test_last_event_id_value_holder_unset() {
    Object holder = new Object();
    LastEventIdValueHolder<Object> value = new LastEventIdValueHolder<>(holder);
    LastEventIdVO vo = LastEventIdVO.from("one");
    value.lastEventId(vo);
    Assertions.assertSame(holder, value.unsetLastEventIdIfMatches("lastEventId_other"));
    Assertions.assertTrue(value.getLastEventIdValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLastEventIdIfMatches("lastEventId"));
    Assertions.assertFalse(value.getLastEventIdValue().isPresent(),
        "The field name must clear the value");
    value.lastEventId(vo);
    Assertions.assertSame(holder, value.unsetLastEventId());
    Assertions.assertFalse(value.getLastEventIdValue().isPresent(), "Unset must clear the value");
  }
}
